package fr.cercle.tourderole;
import android.app.*;import android.net.Uri;import android.os.*;import android.graphics.*;import android.graphics.pdf.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
public final class Documents{
public static void merge(MainActivity a,ArrayList<Uri> uris){if(uris.isEmpty())return;ArrayList<String> names=new ArrayList<>();for(Uri u:uris)names.add(a.label(u));new AlertDialog.Builder(a).setTitle("Fusion en PDF image").setMessage("Ordre de sélection :\n"+android.text.TextUtils.join("\n",names)+"\n\n50 pages maximum. Les textes sélectionnables, liens et signatures ne sont pas conservés. Les originaux restent intacts.").setNegativeButton("Annuler",null).setPositiveButton("Créer le PDF",(d,w)->a.busy("Fusion des PDF",()->{ArrayList<File> files=new ArrayList<>();for(Uri u:uris)files.add(a.file(a.importFile(u)));convert(a,files,null,"Fusion PDF");})).show();}
public static void split(MainActivity a,JSONObject row){EditText input=new EditText(a);input.setHint("1-3,5");new AlertDialog.Builder(a).setTitle("Extraire des pages · PDF image").setMessage("Indique les pages : 1-3,5. 50 pages maximum. Le document produit sera un PDF image. L’original reste intact.").setView(input).setNegativeButton("Annuler",null).setPositiveButton("Extraire",(d,w)->a.busy("Extraction",()->{File file=a.file(row.optString("_file"));ArrayList<Integer> pages;try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer render=new PdfRenderer(fd)){pages=new ArrayList<>(Core.pages(input.getText().toString(),render.getPageCount()));}convert(a,new ArrayList<>(Arrays.asList(file)),pages,"Pages extraites");})).show();}
static void convert(MainActivity a,ArrayList<File> files,List<Integer> selection,String title)throws Exception{int total=0;for(File file:files)try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer r=new PdfRenderer(fd)){total+=selection==null?r.getPageCount():selection.size();}if(total<1||total>50)throw new IOException("Sélectionne entre1 et50pages par opération");String rel="attachments/"+UUID.randomUUID()+".pdf";a.file(rel).getParentFile().mkdirs();PdfDocument document=new PdfDocument();int num=0;try{for(File file:files)try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer r=new PdfRenderer(fd)){ArrayList<Integer> chosen=new ArrayList<>();if(selection==null)for(int i=0;i<r.getPageCount();i++)chosen.add(i);else chosen.addAll(selection);for(int index:chosen)try(PdfRenderer.Page source=r.openPage(index)){int width=Math.min(1400,source.getWidth()*2),height=Math.round(source.getHeight()*(width/(float)source.getWidth()));if(height>2200){width=Math.round(width*2200f/height);height=2200;}Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);source.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_PRINT);PdfDocument.Page page=document.startPage(new PdfDocument.PageInfo.Builder(width,height,++num).create());page.getCanvas().drawBitmap(b,0,0,null);document.finishPage(page);b.recycle();}}try(OutputStream out=new FileOutputStream(a.file(rel))){document.writeTo(out);}}finally{document.close();}JSONObject result=a.insert("documents",title+" · "+Core.today());result.put("_file",rel);result.put("_label",title+".pdf");result.put("_mime","application/pdf");MainActivity.persist(a,a.db);}
}
